set -eu
cd /home/admin1/projects/ai-core
python3 -B - <<'PY'
import os, json, pathlib, grp, pwd, shutil, subprocess, urllib.request
uid=os.getuid()
accounts=pwd.getpwall()
private=[]
for group in grp.getgrall():
    members={p.pw_uid for p in accounts if p.pw_gid==group.gr_gid}
    for name in group.gr_mem:
        try: members.add(pwd.getpwnam(name).pw_uid)
        except KeyError: members.add(-1)
    if members=={uid} and group.gr_gid in set(os.getgroups())|{os.getgid()}:
        private.append(group.gr_gid)
flags=set()
for line in pathlib.Path('/proc/cpuinfo').read_text().splitlines():
    if line.startswith('flags'):
        flags=set(line.split(':',1)[1].split());break
disk=shutil.disk_usage('models')
r={'host_uid':uid,'owner_only_current_groups':sorted(private),'setfacl_available':shutil.which('setfacl') is not None,'cpu_flags':{k:k in flags for k in ('avx2','avx512f','avx512_bf16','amx_bf16')},'models_disk_free_bytes':disk.free,'venv_available':__import__('importlib.util').util.find_spec('venv') is not None,'provider_calls':0}
try:
    req=urllib.request.Request('https://huggingface.co/api/models/Qwen/Qwen3.5-4B?blobs=true',headers={'Accept':'application/json'})
    with urllib.request.urlopen(req,timeout=12) as res:
        d=json.loads(res.read(1024*1024))
    assert d.get('id')=='Qwen/Qwen3.5-4B'
    shards=[{'name':x['rfilename'],'size':x.get('size'),'sha256':(x.get('lfs') or {}).get('sha256')} for x in d.get('siblings',[]) if x.get('rfilename','').endswith('.safetensors')]
    r['official_checkpoint']={'revision':d['sha'],'shards':shards,'total_bytes':sum(x['size'] or 0 for x in shards),'license':(d.get('cardData') or {}).get('license')}
except Exception as e: r['checkpoint_probe_error']=type(e).__name__
body='## Qwen training resource / immutable checkpoint preflight\n\n```json\n'+json.dumps(r,indent=2)+'\n```\n\nRead-only. No package install, model download, secret read, permission change, paid provider call, or training.'
subprocess.run(['gh','issue','comment','1','--repo','seigo-gace/ai-core','--body-file','-'],input=body,text=True,capture_output=True,check=True,timeout=25)
print('DISTILLATION_RESOURCE_PREFLIGHT_RECORDED')
PY
